module sine (
	input wire [17:0] theta,
	output reg signed [13:0] sinval
);

reg [13:0] sinlut [0:65535];

// theta is split into 4 quadrants, only 1st quarter of sine included below
parameter V1QUARTER=18'd65536; // TODO: parameterize for n width theta
parameter V2QUARTER=18'd2 * V1QUARTER;
parameter V3QUARTER=18'd3 * V1QUARTER;

wire [15:0] thetalsbs;
assign thetalsbs=theta[15:0];

always @(*) begin
    //sinval<=sinlut[theta];
    if (theta<V1QUARTER)      sinval<= sinlut[thetalsbs];
    else if (theta<V2QUARTER) sinval<= sinlut[V1QUARTER-thetalsbs];
    else if (theta<V3QUARTER) sinval<= 13'd500; //-sinlut[V2QUARTER-thetalsbs];
    else                       sinval<=-sinlut[thetalsbs];
end

